define(['core/modal_save_cancel','core/modal_events','core/str','core/log'],function(ModalSaveCancel,ModalEvents,Str,Log) {var submitForm=function(form) {if (!form) {return;} if (typeof form.submit==='function') {HTMLFormElement.prototype.submit.call(form);}};var getFocusableElement=function() {var element=document.activeElement;if (!element||element===document.body||typeof element.focus!=='function') {return null;} return element;};var restoreFocus=function(element) {if (!element||typeof element.focus!=='function'||!document.documentElement.contains(element)) {return;} window.setTimeout(function() {try {element.focus({preventScroll:true});} catch (error) {element.focus();}},0);};var focusModal=function(modal) {window.setTimeout(function() {var root=modal&&typeof modal.getRoot==='function'?modal.getRoot():null;var target=null;if (root&&typeof root.find==='function') {target=root.find('.modal-footer .btn-primary, .modal-footer button, .modal-header button, [tabindex]:not([tabindex="-1"])')[0];} if (!target&&root&&root[0]) {target=root[0].querySelector('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');} if (target&&typeof target.focus==='function') {target.focus();}},0);};var resolveString=function(descriptor,fallback) {if (typeof descriptor==='string'&&descriptor.length) {return Promise.resolve(descriptor);} if (descriptor&&descriptor.key) {return Str.get_string(descriptor.key,descriptor.component||'moodle') .catch(function() {return fallback||descriptor.key;});} return Promise.resolve(fallback||'');};var fallbackConfirm=function(form,message) {if (window.confirm(message||'Are you sure?')) {submitForm(form);return true;} return false;};var showModalConfirm=function(form,options,focusReturnElement) {options=options||{};var labels=options.fallbackLabels||{};var message=options.message||labels.message||'';var submitted=false;return Promise.all([resolveString(options.titleString,labels.confirm||'Confirm'),resolveString(options.okString,labels.ok||'OK'),resolveString(options.cancelString,labels.cancel||'Cancel')]).then(function(strings) {return ModalSaveCancel.create({title:strings[0],body:message}).then(function(modal) {modal.setSaveButtonText(strings[1]);modal.setCancelButtonText(strings[2]);modal.getRoot().on(ModalEvents.save,function(event) {event.preventDefault();submitted=true;modal.hide();submitForm(form);});if (ModalEvents.hidden) {modal.getRoot().on(ModalEvents.hidden,function() {if (!submitted) {restoreFocus(focusReturnElement);}});} modal.show();focusModal(modal);});}).catch(function(error) {var logger=options.logger||Log;if (logger&&typeof logger.debug==='function') {logger.debug((options.logPrefix||'mod_videotrack/core/confirm')+': modal fallback: '+error);} if (!fallbackConfirm(form,message)) {restoreFocus(focusReturnElement);}});};return {attachToForms:function(selector,options) {options=options||{};Array.prototype.forEach.call(document.querySelectorAll(selector),function(form) {if (!form||form.dataset.videotrackConfirmAttached==='1') {return;} form.dataset.videotrackConfirmAttached='1';form.addEventListener('submit',function(event) {var focusReturnElement=event.submitter||getFocusableElement();event.preventDefault();showModalConfirm(form,options,focusReturnElement);});});}};});
